package com.tripnest.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="bookings") public class Booking { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true) String reference; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) User user; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="accommodation_id",nullable=false) Accommodation accommodation; @Column(name="check_in") LocalDate checkIn; @Column(name="check_out") LocalDate checkOut; int guests; int nights; @Column(name="price_per_night") BigDecimal pricePerNight; @Column(name="tax_amount") BigDecimal taxAmount; @Column(name="total_amount") BigDecimal totalAmount; @Enumerated(EnumType.STRING) BookingStatus status; @Column(name="created_at") LocalDateTime createdAt; @Column(name="updated_at") LocalDateTime updatedAt; @PrePersist void create(){createdAt=updatedAt=LocalDateTime.now();} @PreUpdate void update(){updatedAt=LocalDateTime.now();} public Long getId(){return id;} public String getReference(){return reference;} public void setReference(String v){reference=v;} public User getUser(){return user;} public void setUser(User v){user=v;} public Accommodation getAccommodation(){return accommodation;} public void setAccommodation(Accommodation v){accommodation=v;} public LocalDate getCheckIn(){return checkIn;} public void setCheckIn(LocalDate v){checkIn=v;} public LocalDate getCheckOut(){return checkOut;} public void setCheckOut(LocalDate v){checkOut=v;} public int getGuests(){return guests;} public void setGuests(int v){guests=v;} public int getNights(){return nights;} public void setNights(int v){nights=v;} public BigDecimal getPricePerNight(){return pricePerNight;} public void setPricePerNight(BigDecimal v){pricePerNight=v;} public BigDecimal getTaxAmount(){return taxAmount;} public void setTaxAmount(BigDecimal v){taxAmount=v;} public BigDecimal getTotalAmount(){return totalAmount;} public void setTotalAmount(BigDecimal v){totalAmount=v;} public BookingStatus getStatus(){return status;} public void setStatus(BookingStatus v){status=v;} }
